        return (
          String(p.manufacturer) + ' ' + String(p.name) +
          '<br>n<sub>d</sub>=' + Number(p.nd).toFixed(5) +
          '<br>V<sub>d</sub>=' + Number(p.vd).toFixed(2) +
          '<br>price=' + priceStr
        );
